# Unified player: release must never synchronously block the input event currently
# running on the main thread. Mark released immediately and queue ExoPlayer.release.
p = Path("app/src/main/java/com/jianglab/babywife/UnifiedMediaPlayer.java")
text = p.read_text(encoding="utf-8")
old = '''    void release() {\n        released = true;\n        userRequestedPlayback = false;\n        communicationPaused = false;\n        preparedListener = null;\n        completionListener = null;\n        errorListener = null;\n        mainHandler.removeCallbacks(communicationModeWatcher);\n        runOnMain(this::releaseInternalPlayer);\n    }'''
new = '''    void release() {\n        if (released) return;\n        released = true;\n        userRequestedPlayback = false;\n        communicationPaused = false;\n        preparedListener = null;\n        completionListener = null;\n        errorListener = null;\n        mainHandler.removeCallbacks(communicationModeWatcher);\n        // Always enqueue the real ExoPlayer release. Calling existing.release()\n        // inline from a song-row MotionEvent can block Xiaomi/Android 16 input\n        // dispatch long enough to trigger a 5-second ANR.\n        mainHandler.post(this::releaseInternalPlayer);\n    }'''
text = replace_once(text, old, new, "nonblocking unified release")
p.write_text(text, encoding="utf-8")

